  "depth-pia-wm-axis": "<svg viewBox=\"0 0 320 200\" role=\"img\" aria-labelledby=\"depth-t\"><title id=\"depth-t\">Depth axis: pia at top, white matter at bottom, y increases downward</title><rect x=\"118\" y=\"32\" width=\"46\" height=\"140\" fill=\"var(--scaffold)\" fill-opacity=\".14\" stroke=\"currentColor\" stroke-opacity=\".6\" stroke-width=\"2\"/><g stroke=\"currentColor\" stroke-opacity=\".25\" stroke-width=\"1.5\"><path d=\"M118,62 H164\"/><path d=\"M118,92 H164\"/><path d=\"M118,122 H164\"/><path d=\"M118,152 H164\"/></g><text x=\"141\" y=\"26\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--muted)\">pia</text><text x=\"141\" y=\"186\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--muted)\">white matter</text><path d=\"M90,32 V170\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\"/><path d=\"M84,162 L90,172 L96,162\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.4\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><text x=\"76\" y=\"30\" font-size=\"10\" class=\"mono\" fill=\"var(--muted)\">0</text><text transform=\"translate(70,102) rotate(-90)\" text-anchor=\"middle\" font-size=\"12\" class=\"mono\" fill=\"var(--accent-ink)\" font-weight=\"600\">+y</text><text x=\"180\" y=\"96\" font-size=\"10.5\" fill=\"var(--muted)\">y increases</text><text x=\"180\" y=\"110\" font-size=\"10.5\" fill=\"var(--muted)\">downward</text><text x=\"180\" y=\"130\" font-size=\"10\" class=\"mono\" fill=\"var(--faint)\">invert_yaxis</text></svg>",
