  "cre-line": "<svg viewBox=\"0 0 320 200\" role=\"img\" aria-labelledby=\"cre-t\"><title id=\"cre-t\">Cre line drives a loxP reporter</title> <g stroke=\"currentColor\" stroke-opacity=\".45\" stroke-width=\"2\" stroke-linecap=\"round\"><path d=\"M20,58 H300\"/><path d=\"M20,138 H300\"/></g> <g fill=\"var(--accent)\" fill-opacity=\".35\" stroke=\"var(--accent)\" stroke-width=\"1.6\" stroke-linejoin=\"round\"> <polygon points=\"86,50 100,58 86,66\"/><polygon points=\"176,50 190,58 176,66\"/><polygon points=\"130,130 144,138 130,146\"/></g> <g fill=\"var(--surface-2)\" stroke=\"currentColor\" stroke-opacity=\".5\" stroke-width=\"1.8\"> <rect x=\"106\" y=\"46\" width=\"64\" height=\"24\" rx=\"4\"/><rect x=\"200\" y=\"46\" width=\"80\" height=\"24\" rx=\"4\"/></g> <g text-anchor=\"middle\" font-size=\"10\" class=\"mono\" fill=\"var(--muted)\"> <text x=\"138\" y=\"63\">STOP</text><text x=\"240\" y=\"63\">reporter</text></g> <g text-anchor=\"middle\" font-size=\"9\" class=\"mono\" fill=\"var(--faint)\"> <text x=\"93\" y=\"38\">loxP</text><text x=\"183\" y=\"38\">loxP</text></g> <path d=\"M138,80 V104\" stroke=\"var(--accent)\" stroke-width=\"2\" stroke-linecap=\"round\"/> <polygon points=\"138,110 133,101 143,101\" fill=\"var(--accent)\"/> <text x=\"152\" y=\"98\" font-size=\"11\" fill=\"var(--accent-ink)\" font-weight=\"600\">Cre</text> <rect x=\"200\" y=\"126\" width=\"80\" height=\"24\" rx=\"4\" fill=\"var(--accent)\" fill-opacity=\".2\" stroke=\"var(--accent)\" stroke-width=\"2.2\"/> <text x=\"240\" y=\"143\" text-anchor=\"middle\" font-size=\"10\" class=\"mono\" fill=\"var(--accent-ink)\" font-weight=\"600\">reporter</text> <text x=\"88\" y=\"143\" text-anchor=\"middle\" font-size=\"9\" fill=\"var(--faint)\">STOP excised</text> <text x=\"160\" y=\"178\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"var(--muted)\">only in Cre+ cells</text> </svg>",
