  "isi-violations": "<svg viewBox=\"0 0 320 200\" role=\"img\" aria-labelledby=\"isiv-t\"><title id=\"isiv-t\">isi_violations: intervals shorter than the refractory period</title><path d=\"M24,120 H296\" stroke=\"currentColor\" stroke-opacity=\".3\" stroke-width=\"1.4\"/><rect x=\"118\" y=\"88\" width=\"13\" height=\"32\" rx=\"2\" fill=\"var(--accent)\" fill-opacity=\".16\"/><path d=\"M40,120 V92\" stroke=\"currentColor\" stroke-opacity=\".8\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><path d=\"M84,120 V92\" stroke=\"currentColor\" stroke-opacity=\".8\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><path d=\"M176,120 V92\" stroke=\"currentColor\" stroke-opacity=\".8\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><path d=\"M220,120 V92\" stroke=\"currentColor\" stroke-opacity=\".8\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><path d=\"M262,120 V92\" stroke=\"currentColor\" stroke-opacity=\".8\" stroke-width=\"2.2\" stroke-linecap=\"round\"/><path d=\"M120,120 V88\" stroke=\"var(--accent)\" stroke-width=\"2.4\" stroke-linecap=\"round\"/><path d=\"M129,120 V88\" stroke=\"var(--accent)\" stroke-width=\"2.4\" stroke-linecap=\"round\"/><path d=\"M120,132 v6 H129 v-6\" fill=\"none\" stroke=\"var(--accent)\" stroke-width=\"1.6\" stroke-linejoin=\"round\"/><text x=\"124\" y=\"154\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"var(--accent-ink)\" font-weight=\"600\">&lt; refractory</text><path d=\"M220,132 v6 H262 v-6\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".4\" stroke-width=\"1.6\" stroke-linejoin=\"round\"/><text x=\"241\" y=\"154\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"var(--faint)\">ISI</text><text x=\"160\" y=\"40\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"var(--muted)\">spikes from two cells merged</text><text x=\"160\" y=\"186\" text-anchor=\"middle\" font-size=\"9\" class=\"mono\" fill=\"var(--faint)\">threshold 0.5</text></svg>",
  "local-field-potential": "<svg viewBox=\"0 0 320 200\" role=\"img\" aria-labelledby=\"lfp-t\"><title id=\"lfp-t\">Local field potential: summed activity of nearby cells</title><circle cx=\"74\" cy=\"108\" r=\"52\" fill=\"var(--scaffold)\" fill-opacity=\".14\" stroke=\"currentColor\" stroke-opacity=\".3\" stroke-width=\"1.6\" stroke-dasharray=\"4 4\"/><path d=\"M66,26 V104 L74,118 L82,104 V26\" fill=\"var(--surface-2)\" stroke=\"currentColor\" stroke-opacity=\".6\" stroke-width=\"2\" stroke-linejoin=\"round\"/><g fill=\"var(--neuron)\" fill-opacity=\".45\" stroke=\"var(--neuron)\" stroke-width=\"1.6\"><circle cx=\"38\" cy=\"88\" r=\"6\"/><circle cx=\"46\" cy=\"136\" r=\"6\"/><circle cx=\"98\" cy=\"82\" r=\"6\"/><circle cx=\"106\" cy=\"130\" r=\"6\"/><circle cx=\"72\" cy=\"152\" r=\"6\"/><circle cx=\"34\" cy=\"116\" r=\"6\"/></g><path d=\"M132,108 H164\" stroke=\"currentColor\" stroke-opacity=\".55\" stroke-width=\"2\" stroke-linecap=\"round\"/><path d=\"M158,104 L164,108 L158,112\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".55\" stroke-width=\"2\" stroke-linecap=\"round\" stroke-linejoin=\"round\"/><path d=\"M176,108 C188,80 200,80 212,108 C220,127 226,131 234,116 C242,101 248,98 256,110 C266,127 274,131 284,108 C291,91 300,92 306,104\" fill=\"none\" stroke=\"var(--accent)\" stroke-width=\"2.4\" stroke-linecap=\"round\"/><text x=\"74\" y=\"180\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"var(--muted)\">many cells, one electrode</text><text x=\"242\" y=\"164\" text-anchor=\"middle\" font-size=\"11\" fill=\"var(--accent-ink)\" font-weight=\"600\">summed potential</text><text x=\"242\" y=\"180\" text-anchor=\"middle\" font-size=\"9.5\" class=\"mono\" fill=\"var(--faint)\">below 250 Hz</text></svg>",
  "locally-sparse-noise": "<svg viewBox=\"0 0 320 200\" role=\"img\" aria-labelledby=\"lsn-t\"><title id=\"lsn-t\">Locally sparse noise with an exclusion zone</title> <rect x=\"34\" y=\"26\" width=\"200\" height=\"128\" rx=\"5\" fill=\"var(--surface-2)\" stroke=\"currentColor\" stroke-opacity=\".4\" stroke-width=\"1.8\"/> <g stroke=\"currentColor\" stroke-opacity=\".12\" stroke-width=\"1\"> <path d=\"M59,26 V154 M84,26 V154 M109,26 V154 M134,26 V154 M159,26 V154 M184,26 V154 M209,26 V154\"/> <path d=\"M34,51 H234 M34,77 H234 M34,103 H234 M34,129 H234\"/></g> <rect x=\"60\" y=\"52\" width=\"24\" height=\"24\" fill=\"currentColor\" fill-opacity=\".65\"/> <rect x=\"160\" y=\"27\" width=\"24\" height=\"24\" fill=\"var(--accent)\" fill-opacity=\".8\"/> <rect x=\"110\" y=\"104\" width=\"24\" height=\"24\" fill=\"var(--accent)\" fill-opacity=\".8\"/> <rect x=\"185\" y=\"129\" width=\"24\" height=\"24\" fill=\"currentColor\" fill-opacity=\".65\"/> <circle cx=\"122\" cy=\"116\" r=\"34\" fill=\"none\" stroke=\"var(--accent)\" stroke-width=\"1.8\" stroke-dasharray=\"4 4\"/> <path d=\"M122,116 L156,116\" stroke=\"var(--accent)\" stroke-width=\"1.4\"/> <text x=\"140\" y=\"112\" font-size=\"9\" class=\"mono\" fill=\"var(--accent-ink)\">5 px</text> <text x=\"252\" y=\"52\" font-size=\"10\" fill=\"var(--muted)\">bright</text> <rect x=\"252\" y=\"60\" width=\"14\" height=\"14\" fill=\"var(--accent)\" fill-opacity=\".8\"/> <text x=\"252\" y=\"98\" font-size=\"10\" fill=\"var(--muted)\">dark</text> <rect x=\"252\" y=\"106\" width=\"14\" height=\"14\" fill=\"currentColor\" fill-opacity=\".65\"/> <text x=\"134\" y=\"176\" text-anchor=\"middle\" font-size=\"9.5\" fill=\"var(--faint)\">no two spots within the zone</text> </svg>",
