  "roi-mask": "<svg viewBox=\"0 0 320 200\" role=\"img\" aria-labelledby=\"roi-t\"><title id=\"roi-t\">ROI mask: the pixels assigned to one segmented cell</title><path d=\"M124,88h16v16h-16zM124,104h16v16h-16zM140,72h16v16h-16zM140,88h16v16h-16zM140,104h16v16h-16zM156,72h16v16h-16zM156,88h16v16h-16zM156,104h16v16h-16zM172,72h16v16h-16zM172,88h16v16h-16zM172,104h16v16h-16zM188,88h16v16h-16zM188,104h16v16h-16z\" fill=\"var(--accent)\" fill-opacity=\".3\"/><path d=\"M92,40V152M108,40V152M124,40V152M140,40V152M156,40V152M172,40V152M188,40V152M204,40V152M220,40V152M236,40V152M252,40V152M92,40H252M92,56H252M92,72H252M92,88H252M92,104H252M92,120H252M92,136H252M92,152H252\" stroke=\"currentColor\" stroke-opacity=\".22\" stroke-width=\"1\"/><rect x=\"92\" y=\"40\" width=\"160\" height=\"112\" fill=\"none\" stroke=\"currentColor\" stroke-opacity=\".5\" stroke-width=\"2\"/><ellipse cx=\"164\" cy=\"98\" rx=\"38\" ry=\"30\" fill=\"none\" stroke=\"var(--neuron)\" stroke-width=\"2.4\"/><text x=\"172\" y=\"26\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"var(--muted)\">imaging plane, pixel grid</text><text x=\"60\" y=\"96\" text-anchor=\"middle\" font-size=\"10.5\" fill=\"var(--accent-ink)\" font-weight=\"600\">mask</text><path d=\"M62,104 V122 C62,130 74,132 96,124\" fill=\"none\" stroke=\"var(--accent)\" stroke-width=\"2\" stroke-linecap=\"round\"/><text x=\"172\" y=\"176\" text-anchor=\"middle\" font-size=\"10\" fill=\"var(--muted)\">one ROI = pixels of one cell</text></svg>",
